WITH gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, device_code, temp_c, humidity, pressure, status_bits, firmware, session_start_flag, session_id, CASE WHEN device_code RLIKE '^(DV-01|DV-04)$' THEN 'GROUP_A' ELSE 'CORE' END AS device_code_zone FROM sessionized ORDER BY firmware;
